{
  "questions": [
    {
      "trigger": "刘注引王隐晋书：'初涛领吏部，潘岳内非之，密为作谣'，而正文末句'或云潘尼作之'",
      "question": "潘岳与潘尼在作谣一事上究竟是何关系？刘注引王隐晋书称潘岳作谣，正文又引或说为潘尼，两者是否同一人，或存在传抄讹误？",
      "why": "正文与刘注对作谣者的记载不一致，直接关系到对故事真实作者及背后政治意图的判定。",
      "needed_sources": "需要更早的版本或类书引文，以及潘岳、潘尼的传记或文集序跋来辨析。"
    },
    {
      "trigger": "刘注引竹林七贤论：'涛之处'，文字中断，未说明涛之处什么",
      "question": "竹林七贤论中'涛之处'之后的内容是什么？是否涉及山涛的为官之道或与竹林诸贤的关系？",
      "why": "该引文被截断，可能包含对山涛的重要评价或事迹，对理解山涛形象及竹林七贤论的整体观点有价值。",
      "needed_sources": "需要《竹林七贤论》的完整辑佚本或类书引文。"
    },
    {
      "trigger": "刘注引文士传：'尼少有清才，文词温雅，初应州辟，终太常卿'，以及刘注'人祖朂尚书左丞，父满平原太守，并以文学称'",
      "question": "潘尼的祖父潘朂、父亲潘满的文学成就具体如何？他们与潘岳家族的关系是否影响潘尼的仕途及文学评价？",
      "why": "刘注特意提及潘尼家世文学传统，可能暗示其作谣的动机或才能来源，但缺乏具体作品和关联证据。",
      "needed_sources": "需要潘尼、潘岳的传记、文集，以及西晋文学家族的相关史料。"
    }
  ],
  "person_connections": [
    {
      "connection": "山涛与和峤、裴楷、王济：正文中三人被并提，且被比喻为牛身上的部件（和峤鞅、裴楷鞦、王济剔嬲），显示他们与山涛在朝堂上关系密切。",
      "evidence": "正文'阁东有大牛，和峤鞅，裴楷鞦，王济剔嬲不得休'"
    },
    {
      "connection": "山涛与司马懿（宣帝）：刘注引宗人语'巨源河内怀人……'及'涛当与景文共纲纪天下者也'，显示山涛早年与司马懿、司马师、司马昭有交往。",
      "evidence": "刘注引文'宗人谓宣帝曰'及'涛当与景文共纲纪天下者也'"
    },
    {
      "connection": "山涛与嵇康：刘注引文'好庄老，与嵇康善'，显示二人有交游。",
      "evidence": "刘注引文'好荘老与嵇康善'"
    },
    {
      "connection": "山涛与石鉴：刘注引文'为河内从事，与石鉴共宿'，显示二人曾同僚共事。",
      "evidence": "刘注引文'为河内从事与石鉴共'"
    },
    {
      "connection": "潘尼与潘岳：正文或说潘尼作谣，刘注引王隐晋书称潘岳作谣，二人同姓潘，且刘注引文士传提及潘尼家世，可能为同族。",
      "evidence": "正文'或云潘尼作之'与刘注引王隐晋书'潘岳内非之，密为作谣'"
    }
  ],
  "appraisals": [
    {
      "appraisal": "山涛被宗人评价为'当与景文共纲纪天下者也'，即认为他将来会与司马师、司马昭共同治理天下。",
      "evaluator": "山涛的宗人（具体姓名不详）",
      "object": "山涛",
      "basis": "刘注引文'宗人谓宣帝曰……涛当与景文共纲纪天下者也'"
    },
    {
      "appraisal": "山涛被描述为'少有器量，宿士犹不慢之'，即年少时就有器量，连老成之士也不怠慢他。",
      "evaluator": "刘注引文（可能为虞预晋书）",
      "object": "山涛",
      "basis": "刘注引文'贫少有器量宿士犹不慢之'"
    },
    {
      "appraisal": "潘尼被评价为'少有清才，文词温雅'。",
      "evaluator": "刘注引文士传",
      "object": "潘尼",
      "basis": "刘注引文'尼少有清才文词温雅'"
    },
    {
      "appraisal": "潘尼的祖父潘朂、父亲潘满被评价为'并以文学称'。",
      "evaluator": "刘注引文士传",
      "object": "潘朂、潘满",
      "basis": "刘注引文'人祖朂尚书左丞父满平原太守并以文学称'"
    }
  ]
}

